"""Database utilities with connection pooling for improved performance."""
from typing import Dict, List, Any, Optional
from contextlib import contextmanager
import threading
import time
from ..config import config


class ConnectionPool:
    """Thread-safe connection pool for database connections."""

    def __init__(self, size: int = None):
        self._size = size or config.database_pool_size
        self._connections: List['MockSession'] = []
        self._available: List[bool] = []
        self._lock = threading.Lock()
        self._init_pool()

    def _init_pool(self):
        """Initialize the connection pool."""
        for _ in range(self._size):
            self._connections.append(MockSession())
            self._available.append(True)

    def acquire(self) -> 'MockSession':
        """Acquire a connection from the pool."""
        with self._lock:
            for i, available in enumerate(self._available):
                if available:
                    self._available[i] = False
                    return self._connections[i]
        return MockSession()  # Overflow

    def release(self, conn: 'MockSession'):
        """Release a connection back to the pool."""
        with self._lock:
            for i, c in enumerate(self._connections):
                if c is conn:
                    self._available[i] = True
                    return


# Global connection pool
_pool: Optional[ConnectionPool] = None


def get_pool() -> ConnectionPool:
    """Get or create the global connection pool."""
    global _pool
    if _pool is None:
        _pool = ConnectionPool()
    return _pool


class MockQuery:
    """Mock query builder for testing without real database."""

    def __init__(self, table: str, session: 'MockSession'):
        self.table = table
        self.session = session
        self._limit = None
        self._offset = None
        self._filters = {}

    def filter(self, **kwargs):
        self._filters.update(kwargs)
        return self

    def limit(self, count: int):
        self._limit = count
        return self

    def offset(self, count: int):
        self._offset = count
        return self

    def all(self) -> List[Dict]:
        data = self.session.get_table_data(self.table)
        if self._filters:
            data = [row for row in data if all(
                row.get(k) == v for k, v in self._filters.items()
            )]
        if self._offset:
            data = data[self._offset:]
        if self._limit:
            data = data[:self._limit]
        return data

    def first(self) -> Optional[Dict]:
        results = self.all()
        return results[0] if results else None


class MockSession:
    """Mock database session for testing."""

    def __init__(self):
        self._data = {
            'users': self._generate_mock_users(),
            'sessions': [],
            'api_requests': []
        }
        self._last_activity = time.time()

    def _generate_mock_users(self) -> List[Dict]:
        return [
            {'id': i, 'username': f'user{i}', 'email': f'user{i}@example.com', 'role': 'user'}
            for i in range(1, 101)
        ]

    def is_healthy(self) -> bool:
        return time.time() - self._last_activity < 300

    def query(self, table: str) -> MockQuery:
        self._last_activity = time.time()
        return MockQuery(table, self)

    def get_table_data(self, table: str) -> List[Dict]:
        return self._data.get(table, [])

    def count(self, table: str, **filters) -> int:
        data = self._data.get(table, [])
        if filters:
            data = [row for row in data if all(
                row.get(k) == v for k, v in filters.items()
            )]
        return len(data)

    def insert(self, table: str, data: Dict) -> Dict:
        existing_data = self._data.get(table, [])
        new_id = max([row.get('id', 0) for row in existing_data], default=0) + 1
        new_row = {'id': new_id, **data}
        self._data[table].append(new_row)
        return new_row

    def commit(self):
        pass

    def rollback(self):
        pass


def get_db_session() -> MockSession:
    return get_pool().acquire()


@contextmanager
def transaction():
    pool = get_pool()
    session = pool.acquire()
    try:
        yield session
        session.commit()
    except Exception:
        session.rollback()
        raise
    finally:
        pool.release(session)

